"""Topic path subscription matcher."""
def is_topic_subscribed(subscribed_pattern: str, event_topic: str) -> bool:
    """
    Checks if an event topic matches a subscription pattern according to hierarchical
    access control rules.

    - Segments are delimited by `::`.
    - `*` matches exactly one segment.
    - `**` matches zero or more segments.
    - Literal segments must match exactly.
    """
    pattern_segments = subscribed_pattern.split("::")
    topic_segments = event_topic.split("::")

    p_idx = 0  # pattern index
    t_idx = 0  # topic index

    # Helper function for recursive matching of **
    def match_recursive(p_start, t_start):
        p_current = p_start
        t_current = t_start

        while p_current < len(pattern_segments) and t_current < len(topic_segments):
            pattern_segment = pattern_segments[p_current]
            topic_segment = topic_segments[t_current]

            if pattern_segment == "**":
                # '**' can match 0 or more segments.
                # Try matching 0 segments first (i.e., skip '**' in pattern).
                # Then try matching 1 segment, 2 segments, etc., from topic.
                for i in range(t_current, len(topic_segments) + 1):
                    if match_recursive(p_current + 1, i):
                        return True
                return False # No sub-match found for this '**'
            elif pattern_segment == "*":
                # '*' matches exactly one segment, so advance both.
                p_current += 1
                t_current += 1
            elif pattern_segment == topic_segment:
                # Literal match, advance both.
                p_current += 1
                t_current += 1
            else:
                # Mismatch for literal segment.
                return False

        # After loop, check if both pattern and topic are fully consumed.
        # Handle remaining '**' in pattern
        while p_current < len(pattern_segments) and pattern_segments[p_current] == "**":
            p_current += 1

        return p_current == len(pattern_segments) and t_current == len(topic_segments)

    return match_recursive(0, 0)


def clean_topic_segment(topic: str) -> str:
    return topic.strip().lower()

def is_wildcard_subscription(pattern: str) -> bool:
    return pattern.strip() in ("*", "**")
